-- Pilot standardu treści: Frasassi (przystanki 20–23). Wersja redakcyjna z przypisami do ops.stop_research.
-- NIE publikuje na stronę: publikacja (ops.stop_publish_pl + content_v2) dopiero po akceptacji JP.
BEGIN;
INSERT INTO ops.stop_research (stop_id, marked, state, sources, check_result, checked_at, updated_at) VALUES (20, $j${"desc_paragraphs": ["Duży parking jest przy kasach jaskiń, w miejscowości San Vittore delle Chiuse; według przewodnika dla rodzin jest bezpłatny, ale zasady parkowania mogą się zmieniać, więc sprawdźcie na miejscu [1]. Kampery też tu staną [1]. Do samego wejścia do jaskiń dowozi autobus, którego przejazd jest wliczony w bilet [1].", "Kolejność na miejscu: kasa albo, jeśli kupiliście bilety przez internet, od razu przystanek autobusu do jaskiń. Z biletem kupionym online bądźcie tam co najmniej 15 minut przed godziną wejścia z biletu [1]. W weekendy i święta lepiej zarezerwować bilety wcześniej przez internet [1]. Zwiedzanie odbywa się o godzinie wpisanej na bilecie."], "legend": null, "curiosity": null, "fun_fact": null, "pop_culture": null}$j$::jsonb, $j${"legend": {"state": "none", "checked": "przystanek praktyczny (parking) — pytania §2 nie dotyczą"}, "curiosity": {"state": "none", "checked": "przystanek praktyczny (parking) — pytania §2 nie dotyczą"}, "fun_fact": {"state": "none", "checked": "przystanek praktyczny (parking) — pytania §2 nie dotyczą"}, "pop_culture": {"state": "none", "checked": "przystanek praktyczny (parking) — pytania §2 nie dotyczą"}}$j$::jsonb, $j$[{"n": 1, "url": "https://www.viaggiapiccoli.com/grotte-di-frasassi/", "title": "Grotte di Frasassi con i bambini (ViaggiaPiccoli)", "lang": "it", "accessed": "2026-10-18"}]$j$::jsonb, $j${"sources": "ViaggiaPiccoli sprawdzone przez Claude 18.10 (parking, autobus w bilecie, 15 min, rezerwacja)", "dup": "ok", "sense": "ok; poprzednia wersja miała 45 min bez źródła — zmienione na 15 min wg źródła", "flags": ["parking bez ciekawostki — do decyzji JP"], "verdict": "ok", "by": "Claude", "date": "2026-10-18"}$j$::jsonb, now(), now())
  ON CONFLICT (stop_id) DO UPDATE SET marked=EXCLUDED.marked, state=EXCLUDED.state, sources=EXCLUDED.sources, check_result=EXCLUDED.check_result, checked_at=now(), updated_at=now();
INSERT INTO ops.stop_research (stop_id, marked, state, sources, check_result, checked_at, updated_at) VALUES (21, $j${"desc_paragraphs": ["25 września 1971 roku Rolando Silvestri z klubu Gruppo Speleologico Marchigiano CAI w Ankonie zauważył, że z małego otworu na zboczu góry wydobywa się silny prąd powietrza: znak, że w środku jest wielka pustka [2][7]. Wyprawą dowodził Giancarlo Cappanera [2][3][7]. Odkrywcy wrzucili w szczelinę kamień i z czasu spadania oszacowali głębokość na ponad sto metrów; lin, które mieli ze sobą, nie wystarczyło, żeby dosięgnąć dna [2][7]. Pierwszą salę nazwali Abisso Ancona, na cześć swojego miasta [2]. Ma ponad 2 miliony metrów sześciennych objętości [10][20].", "Jaskinie wyrzeźbiła woda. Około miliona lat temu rzeka Sentino płynęła w wąwozie znacznie wyżej niż dziś. Jej zimna woda mieszała się z siarkową wodą podchodzącą z głębi, a taka mieszanka rozpuszczała wapień dużo szybciej niż zwykła woda [2][14]. W środku przez cały rok jest stałe 14 stopni [2][4], a wilgotność sięga prawie stu procent [2]. Część jaskiń otwarto dla zwiedzających 1 września 1974 roku [1][2][4].", "Trasa turystyczna ma około półtora kilometra [1] i zajmuje około godziny i kwadransa [4]. Prowadzi przez kilka sal, między innymi Abisso Ancona, Salę 200, Salę Świeczek, Salę Niedźwiedzicy i Salę Nieskończoności [1]. W Abisso Ancona stoją „Giganci”, stalagmity wysokie na około 20 metrów [8][16]. Sala 200 to korytarz długi na 200 metrów, stąd nazwa; na jej środku stoi Obelisk, stalagmit wysoki na 15 metrów [2]. Szukajcie też Miecza Damoklesa, największego stalaktytu jaskini: ma 7,40 metra długości i 150 centymetrów średnicy [2].", "Sala Świeczek zawdzięcza nazwę mnóstwu małych, walcowatych stalagmitów, które wyglądają jak świeczki na podstawkach [2][8]. W Sali Niedźwiedzicy woda wyrzeźbiła głaz przypominający niedźwiedzia [2]. A Sala Nieskończoności ma swoją nazwę od odkrywców, którzy stracili w niej orientację i kilka razy obeszli ją dookoła, zanim znaleźli drogę dalej [2]. Organowe Piszczałki, cienkie kamienne formy, dźwięczą, gdy się w nie uderzy [2].", "Praktycznie: w jaskini jest chłodno i wilgotno, więc nawet latem weźcie bluzy dla wszystkich i wygodne buty [4]. Osoby o ograniczonej mobilności i wózki dojadą tylko do początku drugiej sali, Sali 200 [4][33]."], "legend": {"text": "Nad wąwozem Frasassi stoi średniowieczny zamek Pierosara, a z jego nazwą wiąże się legenda. Sara była zaręczona z Pierem. Zakochał się w niej hrabia Rovellone, pan sąsiedniego zamku Rotorscio, i pewnej nocy wdarł się do twierdzy, żeby ją porwać. Mieszkańcy zamknęli bramy i stanęli do walki. Osaczony hrabia zabił Sarę, a śmiertelnie ranny Piero skonał u jej boku. Od imion zakochanych zamek, nazywany wcześniej Castel Petroso, miał dostać nazwę Pierosara [21].", "trace": "Ze średniowiecznego zamku przetrwały mury, bramy, wieża i kościół San Sebastiano [21]. Pierosara jest jednym z przystanków turystycznego paszportu Frasassi [22].", "history": "W dokumentach z 981 roku pojawia się okręg Castel Petroso, a w 1212 roku zamek przeszedł pod władzę Fabriano [21]. Strzegł wejścia do wąwozów Frasassi i Rossa [21]. Opowieść o Pierze i Sarze to legenda, nie wydarzenie potwierdzone w źródłach [21]."}, "curiosity": {"text": "W niższych, wciąż aktywnych korytarzach Frasassi płyną strumienie z siarkowodorem, a na ścianach zwisają śluzowate sople bakterii, nazywane przez naukowców „snottites” (od angielskiego „snot”, czyli smark) [11]. Są kwaśne jak elektrolit w akumulatorze: mają pH 0–1 [11][26]. Bakterie czerpią energię z siarkowodoru i tlenu, a jako produkt uboczny wytwarzają kwas siarkowy, który rozpuszcza wapień i przyspiesza powstawanie jaskini [11][12]. Takie życie bez światła słonecznego zainteresowało NASA: jej Instytut Astrobiologii finansował badania genomów tych bakterii w programie o przystosowaniu życia poza Ziemią [26]."}, "fun_fact": {"text": "Czy wiesz, że w pierwszej sali jaskini, Abisso Ancona, zmieściłaby się cała katedra w Mediolanie [2][10][13][16]?"}, "pop_culture": {"items": [{"title": "Grotto", "year": "2016", "text": "Familijny film fantasy w reżyserii Micol Pallucci, nakręcony w całości w Grotte di Frasassi. Grupa dzieci trafia do podziemnego świata, a przewodnikiem jest gadający stalagmit Grotto [28][29]. Wygrał Giffoni Film Festival 2015 w kategorii filmów +6 [29]."}, {"title": "Gormiti – The New Era", "year": "2024", "text": "Aktorski serial dla dzieci, kręcony między innymi w jaskiniach Frasassi; emitowały go Rai2, Rai Gulp i RaiPlay [30][31]."}, {"title": "Il Volo w jaskini", "year": "2021", "text": "26 września 2021 roku, na 50-lecie odkrycia, trio Il Volo zaśpiewało w Grotte di Frasassi [9]."}]}}$j$::jsonb, $j${"legend": {"state": "found"}, "curiosity": {"state": "found"}, "fun_fact": {"state": "found"}, "pop_culture": {"state": "found"}}$j$::jsonb, $j$[{"n": 1, "url": "https://fondoambiente.it/luoghi/grotte-di-frasassi", "title": "Grotte di Frasassi (FAI)", "lang": "it", "accessed": "2026-10-18"}, {"n": 2, "url": "https://it.wikipedia.org/wiki/Grotte_di_Frasassi", "title": "Grotte di Frasassi (it.wikipedia)", "lang": "it", "accessed": "2026-10-18"}, {"n": 3, "url": "https://en.wikipedia.org/wiki/Frasassi_Caves", "title": "Frasassi Caves (en.wikipedia)", "lang": "en", "accessed": "2026-10-18"}, {"n": 4, "url": "https://www.frasassi.com/it/attivita/percorso-turistico/", "title": "Percorso turistico (frasassi.com, operator)", "lang": "it", "accessed": "2026-10-18"}, {"n": 7, "url": "https://www.quotidiano.net/speciali/cultura/grotte-di-frasassi-da-vivere-5036c0a5", "title": "Grotte di Frasassi da vivere (Quotidiano.net)", "lang": "it", "accessed": "2026-10-18"}, {"n": 8, "url": "https://www.familygo.eu/vacanze-con-bambini/viaggi/marche/grotte-di-frasassi-con-bambini-curiosita-info/", "title": "Grotte di Frasassi con bambini (FamilyGo)", "lang": "it", "accessed": "2026-10-18"}, {"n": 9, "url": "https://www.lapresse.it/spettacoli/musica/2021/09/26/il-volo-canta-nelle-grotte-di-frasassi-per-i-50-anni-dalla-scoperta/", "title": "Il Volo canta nelle Grotte di Frasassi (LaPresse)", "lang": "it", "accessed": "2026-10-18"}, {"n": 10, "url": "https://italia.googleblog.com/2015/07/meraviglie-sotterranee-su-street-view.html", "title": "Meraviglie sotterranee su Street View (Google Italia)", "lang": "it", "accessed": "2026-10-18"}, {"n": 11, "url": "https://www.psu.edu/news/research/story/snottites-other-biofilms-hasten-cave-formation", "title": "Snottites, other biofilms hasten cave formation (Penn State)", "lang": "en", "accessed": "2026-10-18"}, {"n": 12, "url": "https://digitalcommons.usf.edu/kip_articles/1903", "title": "Jones, Polerecky, Galdenzi 2015, Chemical Geology 410", "lang": "en", "accessed": "2026-10-18"}, {"n": 13, "url": "https://www.sportoutdoor24.it/viaggi/italia/grotte-di-frasassi/", "title": "Grotte di Frasassi (SportOutdoor24)", "lang": "it", "accessed": "2026-10-18"}, {"n": 14, "url": "https://www.italia.it/it/marche/ancona/grotte-di-frasassi", "title": "Grotte di Frasassi (italia.it)", "lang": "it", "accessed": "2026-10-18"}, {"n": 16, "url": "https://nuvomagazine.com/daily-edit/the-underground-world-of-the-frasassi-caves", "title": "The underground world of the Frasassi Caves (Nuvo)", "lang": "en", "accessed": "2026-10-18"}, {"n": 20, "url": "https://www.panorama.it/tempo-libero/viaggi/grotte-frasassi-marche-grotta-del-vento-toscana", "title": "Grotte di Frasassi e Grotta del Vento (Panorama)", "lang": "it", "accessed": "2026-10-18"}, {"n": 21, "url": "https://www.sportoutdoor24.it/?p=675205", "title": "La leggenda di Pierosara (SportOutdoor24)", "lang": "it", "accessed": "2026-10-18"}, {"n": 22, "url": "https://www.frasassi.com/en/passport/", "title": "Tourist Passport (frasassi.com)", "lang": "en", "accessed": "2026-10-18"}, {"n": 26, "url": "https://astrobiology.nasa.gov/nai/annual-reports/2007/psu/genomics-of-sulfidic-cave-extremophiles-supplement-to-nna04cc06a/index.html", "title": "Genomics of sulfidic cave extremophiles (NASA Astrobiology Institute)", "lang": "en", "accessed": "2026-10-18"}, {"n": 28, "url": "https://www.cinemaitaliano.info/news/34379/grotto-al-cinema-in-2d-e-3d-dal-24-marzo.html", "title": "Grotto al cinema (CinemaItaliano)", "lang": "it", "accessed": "2026-10-18"}, {"n": 29, "url": "https://www.panorama.it/grotto-film-grotte-frasassi-backstage", "title": "Grotto, backstage (Panorama)", "lang": "it", "accessed": "2026-10-18"}, {"n": 30, "url": "https://www.ilrestodelcarlino.it/ancona/cronaca/le-grotte-di-frasassi-ospiteranno-la-serie-tv-gormiti-the-new-era-2c98d97d", "title": "Gormiti The New Era nelle grotte (il Resto del Carlino)", "lang": "it", "accessed": "2026-10-18"}, {"n": 31, "url": "https://www.ilrestodelcarlino.it/ancona/cultura/grotte-di-frasassi-casa-dei-gormiti-anteprima-sanremo-06e827f2", "title": "Grotte di Frasassi casa dei Gormiti (il Resto del Carlino)", "lang": "it", "accessed": "2026-10-18"}, {"n": 33, "url": "https://www.viaggiapiccoli.com/grotte-di-frasassi/", "title": "Grotte di Frasassi con i bambini (ViaggiaPiccoli)", "lang": "it", "accessed": "2026-10-18"}]$j$::jsonb, $j${"sources": "cytaty ze źródeł zebrane przez research 18.10; frasassigsm.it niedostępne", "dup": "temperatura tylko raz w opisie; katedra tylko w fun fakcie", "sense": "data odkrycia 25.09.1971 (5 źródeł; italia.it podaje 29.09); wysokość Abisso Ancona pominięta (200 m vs 100 m); usunięte z opisu bez źródła: Wielki Kanion, przewodnik po włosku", "flags": ["kids_box: 'stalaktyt rośnie ok. 1 mm na 10 lat' — brak źródła, do poprawy", "legenda Pierosary dotyczy zamku nad wąwozem, jedno źródło + paszport frasassi.com", "snottites: miejsce występowania (niższe poziomy) wywnioskowane z [11][12]"], "verdict": "ok", "by": "Claude", "date": "2026-10-18"}$j$::jsonb, now(), now())
  ON CONFLICT (stop_id) DO UPDATE SET marked=EXCLUDED.marked, state=EXCLUDED.state, sources=EXCLUDED.sources, check_result=EXCLUDED.check_result, checked_at=now(), updated_at=now();
INSERT INTO ops.stop_research (stop_id, marked, state, sources, check_result, checked_at, updated_at) VALUES (22, $j${"desc_paragraphs": ["Z daleka San Vittore alle Chiuse wygląda bardziej jak mała forteca niż kościół: zwarta kamienna bryła, po jednej stronie niska okrągła wieża, po drugiej masywna, ścięta dzwonnica [1][2][4]. Uchodzi za jeden z najważniejszych przykładów architektury romańskiej w regionie Marche [4][14]. Według miejscowego przekazu przydomek „delle Chiuse”, czyli „w zamknięciu”, wziął się stąd, że góry otaczają to miejsce, jakby chciały je ukryć [5].", "Klasztor benedyktynów pojawia się w dokumentach już w 1007 roku, a sam kościół zbudowano najpewniej w latach 1060–1080 [1][2]. Benedyktyni to mnisi żyjący wspólnie według reguły świętego Benedykta, w rytmie modlitwy i pracy. Na początku XIII wieku opactwo było u szczytu znaczenia i podlegały mu 42 kościoły [1][2]. W XV wieku klasztor zlikwidowano i z jego zabudowań przetrwało tylko kilka pomieszczeń [1]. W 1902 roku kościół uznano za pomnik narodowy, a w latach 1925–1932 gruntownie go odnowiono [4][6].", "Kościół jest romański: to styl z czasów, gdy stawiano grube kamienne mury z małymi oknami, dlatego wnętrze jest surowe i dość ciemne [2][3][8]. Zbudowano go z miejscowego wapienia na planie krzyża greckiego wpisanego w prawie kwadratowy obrys [1][2]. Krzyż grecki ma cztery ramiona równej długości, jak znak plus, więc kościół nie ma jednej długiej nawy prowadzącej do ołtarza. Cztery okrągłe filary dzielą wnętrze na dziewięć pól, a nad środkowym wznosi się kopuła na ośmiobocznym bębnie [1].", "Stańcie pod kopułą, dokładnie pośrodku: w każdą stronę widać mniej więcej tyle samo przestrzeni i po tym najłatwiej rozpoznać plan krzyża greckiego. Potem obejdźcie kościół z zewnątrz. Półkoliste wybrzuszenia murów to absydy, czyli wnęki zamknięte półkolem; jest ich pięć [1], a tylko północna zachowała pierwotną dekorację [3]. Przy lewych drzwiach w pobliżu ołtarza wyryto w kamieniu znak przypominający odwrócony symbol nieskończoności; jego znaczenia nie udało się wyjaśnić do dziś [6][7][8].", "Naprzeciw kościoła przez rzekę Sentino przerzucony jest kamienny most: z jednej strony ma łuk ostry, z drugiej półokrągły, a wchodzi się na niego przez ufortyfikowaną wieżę [7]. Kilka kroków dalej biją siarkowe źródła San Vittore Terme, czuć je w powietrzu. Z tej wody korzystali już Rzymianie, a pierwszy mały zakład kąpielowy otwarto tu w 1922 roku [11]."], "legend": null, "curiosity": {"text": "W 1976 roku, podczas budowy tunelu drogi S.S. 76 w pobliskim Camponocecchio, miejscowy badacz trafił na skamieniałego ichtiozaura, morskiego gada podobnego do delfina [4][9][10]. Szkielet wydobyto razem z płytą skalną, pokazano w 1980 roku na wystawie w Weronie i na długie lata o nim zapomniano [9][13]. Dopiero w latach 2016–2017 naukowcy uznali go za nowy, nieznany wcześniej gatunek i nazwali Gengasaurus nicosiai, czyli „jaszczur z Gengi” [12][13]. Można go zobaczyć w Muzeum Speleopaleontologicznym, urządzonym w dawnym klasztorze tuż obok kościoła [9][10]."}, "fun_fact": {"text": "Czy wiesz, że w muzeum obok kościoła leży morski gad długi na około 3 metry, który pływał w morzu w tym miejscu około 150 milionów lat temu [4][12][14]?"}, "pop_culture": null}$j$::jsonb, $j${"legend": {"state": "none", "checked": "FAI, italia.it, en.wikipedia, opracowanie kościołów romańskich prowincji Ancona (PDF), greenMe, e-borghi, SiViaggia, komoot — tylko przekaz o nazwie „delle Chiuse” i niewyjaśniony znak, bez opowieści z przebiegiem i zakończeniem"}, "curiosity": {"state": "found"}, "fun_fact": {"state": "found"}, "pop_culture": {"state": "none", "checked": "FAI (tylko ranking Luoghi del Cuore i Giornate FAI), italia.it, en.wikipedia, greenMe, e-borghi, SiViaggia — brak filmów, seriali, książek"}}$j$::jsonb, $j$[{"n": 1, "url": "https://www.famigliedellavisitazione.it/wp/wp-content/uploads/Chiese_paleocristiane_romaniche_in_Italia/PROVINCIA%20DI%20ANCONA/ANCONA-Genga-Abbazia-di-S.Vittore-alle-Chiuse.pdf", "title": "ANCONA Genga Abbazia di S. Vittore alle Chiuse", "lang": "it", "accessed": "2026-10-18"}, {"n": 2, "url": "https://www.museionline.info/marche-musei-monumenti/abbazia-di-san-vittore-alle-chiuse", "title": "Abbazia di San Vittore alle Chiuse (MuseiOnline)", "lang": "it", "accessed": "2026-10-18"}, {"n": 3, "url": "https://en.wikipedia.org/wiki/San_Vittore_alle_Chiuse", "title": "San Vittore alle Chiuse", "lang": "en", "accessed": "2026-10-18"}, {"n": 4, "url": "https://www.italia.it/it/marche/genga/abbazia-san-vittore-delle-chiuse", "title": "Abbazia San Vittore delle Chiuse (italia.it)", "lang": "it", "accessed": "2026-10-18"}, {"n": 5, "url": "https://fondoambiente.it/luoghi/abbazia-di-svittore-delle-chiuse", "title": "Abbazia di S. Vittore delle Chiuse (FAI)", "lang": "it", "accessed": "2026-10-18"}, {"n": 6, "url": "https://www.greenme.it/viaggi/italia/tra-le-montagne-marchigiane-si-nasconde-unabbazia-che-sembra-uscita-da-unaltra-epoca/", "title": "Tra le montagne marchigiane si nasconde un'abbazia… (greenMe)", "lang": "it", "accessed": "2026-10-18"}, {"n": 7, "url": "https://siviaggia.it/idee-di-viaggio/genga-marche-cosa-vedere/538944/", "title": "Cosa fare e vedere a Genga (SiViaggia)", "lang": "it", "accessed": "2026-10-18"}, {"n": 8, "url": "https://www.e-borghi.com/en/what-to-see/genga-abbey-of-san-vittore-alle-chiuse/", "title": "Genga, Abbey of San Vittore alle Chiuse (e-borghi)", "lang": "en", "accessed": "2026-10-18"}, {"n": 9, "url": "https://cultura.gov.it/luogo/museo-speleopaleontologico-ed-archeologico", "title": "Museo Speleopaleontologico ed Archeologico (Ministero della Cultura)", "lang": "it", "accessed": "2026-10-18"}, {"n": 10, "url": "https://www.isprambiente.gov.it/it/attivita/museo/regioni/musei/museo-speleo-paleontologico-e-archeologico-di-genga", "title": "Museo speleo-paleontologico e archeologico di Genga (ISPRA)", "lang": "it", "accessed": "2026-10-18"}, {"n": 11, "url": "https://termedifrasassi.it/wp-content/uploads/2024/04/Carta-servizi-Terme-San-Vittore_15-agg.-02_04_2024.pdf", "title": "Carta servizi Terme San Vittore", "lang": "it", "accessed": "2026-10-18"}, {"n": 12, "url": "https://en.wikipedia.org/wiki/Gengasaurus", "title": "Gengasaurus", "lang": "en", "accessed": "2026-10-18"}, {"n": 13, "url": "https://www.scientificamerican.com/blog/laelaps/paleo-profile-the-genga-lizard/", "title": "Paleo Profile: The Genga Lizard (Scientific American)", "lang": "en", "accessed": "2026-10-18"}, {"n": 14, "url": "https://www.touringclub.it/notizie/bandiere-arancioni/genga-da-scoprire-la-terza-tappa-di-va-dove-ti-porta-il-touring", "title": "Genga da scoprire (Touring Club Italiano)", "lang": "it", "accessed": "2026-10-18"}]$j$::jsonb, $j${"sources": "cytaty ze źródeł zebrane przez research 18.10", "dup": "ichtiozaur: ciekawostka + fun fact (rozwinięcie dla dziecka), w opisie brak", "sense": "chronologia 1007 → 1060–80 → XIII w. → XV w. → 1902 → 1925–32 spójna", "flags": [], "verdict": "ok", "by": "Claude", "date": "2026-10-18"}$j$::jsonb, now(), now())
